// Native packaged-app QA. All data is generated by the app's demo action.
// System Trash restoration is performed through an official system Trash tool;
// record whether that was a GUI file manager or the standard XDG CLI.
import { _electron as electron } from 'playwright';
import assert from 'node:assert/strict';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';

const out = path.resolve(process.env.AGENTVAC_QA_OUT || 'docs/native-linux');
const resultPath = path.join(out, 'package-trash-results.json');
const result = { startedAt: new Date().toISOString(), platform: process.platform, checks: [], status: 'running' };
let app;
let page;
const save = async () => fs.writeFile(resultPath, JSON.stringify(result, null, 2));
const hash = async (file) => createHash('sha256').update(await fs.readFile(file)).digest('hex');
const exists = async (file) => fs.access(file).then(() => true, () => false);
try {
  await fs.mkdir(out, { recursive: true });
  await save();
  app = await electron.launch({ executablePath: path.resolve(process.env.AGENTVAC_QA_EXECUTABLE || 'release-final/linux/linux-unpacked/agentvac'), chromiumSandbox: true, args: [], timeout: 30000 });
  page = await app.firstWindow();
  result.runtime = await app.evaluate(({ app, BrowserWindow }) => ({
    packaged: app.isPackaged,
    electron: process.versions.electron,
    appPath: app.getAppPath(),
    launchArgs: process.argv,
    preferences: BrowserWindow.getAllWindows()[0].webContents.getLastWebPreferences(),
  }));
  assert.equal(result.runtime.packaged, true);
  assert.ok(!result.runtime.launchArgs.includes('--no-sandbox'), 'Chromium process sandbox must stay enabled');
  result.runtime.chromiumSandboxRequested = true;
  assert.equal(result.runtime.preferences.sandbox, true);
  assert.equal(result.runtime.preferences.contextIsolation, true);
  assert.equal(result.runtime.preferences.nodeIntegration, false);
  result.checks.push('packaged Electron window; sandbox and context isolation enabled; renderer Node integration disabled');
  await page.getByRole('button', { name: '体验演示扫描', exact: true }).click();
  await page.getByRole('button', { name: '文件', exact: true }).click();
  result.demoRoot = (await page.evaluate(() => window.agentvac.getContext())).root;
  assert.ok(path.basename(result.demoRoot).startsWith('agentvac-demo-'));
  await page.getByRole('checkbox', { name: '选择当前列表中的安全项目', exact: true }).check();
  await page.getByRole('button', { name: '预览隔离操作', exact: true }).click();
  await page.getByRole('dialog').getByRole('checkbox').check();
  await page.getByRole('dialog').getByRole('button', { name: '确认演示隔离', exact: true }).click();
  await page.getByRole('button', { name: '查看隔离记录', exact: true }).click();
  const rows = await page.evaluate(() => window.agentvac.history());
  const batch = rows.find(row => row.items.some(item => item.status === 'quarantined'));
  assert.ok(batch);
  result.batchId = batch.id;
  result.batchDirectory = path.join(result.demoRoot, '.agentvac-quarantine', batch.id);
  result.files = [];
  for (const item of batch.items.filter(item => item.status === 'quarantined')) {
    result.files.push({ path: item.path, size: item.size, sha256: await hash(path.join(result.batchDirectory, item.id + '.data')) });
  }
  result.checks.push('generated fixture quarantine through real packaged preload/IPC');
  await page.screenshot({ path: path.join(out, 'package-before-system-trash.png'), animations: 'disabled' });
  await page.getByRole('button', { name: '移入系统回收站', exact: true }).first().click();
  const dialog = page.getByRole('dialog');
  assert.equal(await dialog.getByRole('button', { name: '确认移入系统回收站', exact: true }).isDisabled(), true);
  await dialog.getByRole('checkbox').check();
  await dialog.getByPlaceholder('回收站', { exact: true }).fill('回收站');
  await page.screenshot({ path: path.join(out, 'package-system-trash-confirmation.png'), animations: 'disabled' });
  await dialog.getByRole('button', { name: '确认移入系统回收站', exact: true }).click();
  await page.getByRole('heading', { name: '隔离批次已移入系统回收站', exact: true }).waitFor({ timeout: 20000 });
  assert.equal(await exists(result.batchDirectory), false);
  const trashed = (await page.evaluate(() => window.agentvac.history())).find(row => row.id === batch.id);
  assert.ok(trashed.items.every(item => item.status === 'trashed'));
  result.checks.push('real Electron shell.trashItem accepted generated batch; original directory absent; signed history reports trashed');
  await page.getByRole('button', { name: '完成', exact: true }).click();
  await page.screenshot({ path: path.join(out, 'package-system-trash-complete.png'), animations: 'disabled' });
  result.status = 'awaiting_system_trash_restore';
  await save();
  console.log('WAITING FOR STANDARD SYSTEM TRASH RESTORE OF BATCH', batch.id, 'TO', result.batchDirectory);
  const deadline = Date.now() + 20 * 60 * 1000;
  while (!await exists(result.batchDirectory)) {
    if (Date.now() >= deadline) throw new Error('Timed out awaiting system Trash restoration of generated fixture batch.');
    await new Promise(resolve => setTimeout(resolve, 500));
  }
  result.checks.push('whole generated batch returned from system Trash to its original quarantine directory');
  await page.getByRole('button', { name: '文件', exact: true }).click();
  await page.getByRole('button', { name: '隔离记录', exact: true }).click();
  await page.getByRole('button', { name: '恢复此批次', exact: true }).first().click();
  await page.getByRole('dialog').getByRole('button', { name: '确认恢复', exact: true }).click();
  await page.getByRole('button', { name: '完成', exact: true }).click();
  const restored = (await page.evaluate(() => window.agentvac.history())).find(row => row.id === batch.id);
  assert.ok(restored.items.every(item => item.status === 'restored'));
  for (const file of result.files) assert.equal(await hash(path.join(result.demoRoot, file.path)), file.sha256);
  result.checks.push('app restored every file after OS Trash round-trip; SHA-256 matches quarantined fixture bytes');
  await page.screenshot({ path: path.join(out, 'package-system-trash-roundtrip-restored.png'), animations: 'disabled' });
  result.status = 'passed';
  result.finishedAt = new Date().toISOString();
  await save();
  console.log('PASS packaged native system Trash round-trip and byte-exact app restoration');
} catch (error) {
  result.status = 'failed';
  result.error = String(error?.stack || error);
  result.finishedAt = new Date().toISOString();
  if (page) {
    result.visibleText = await page.locator('body').innerText().catch(() => 'Unavailable');
    await page.screenshot({ path: path.join(out, 'package-system-trash-failure.png'), animations: 'disabled' }).catch(() => {});
  }
  await save();
  console.error(result.error);
  process.exitCode = 1;
} finally {
  await app?.close();
}
